// Audiencias de Meta. «listar» trae audiencias, formularios y posts recientes de cada marca;
// «crear» hace las audiencias base que falten; «similar» crea una similar 1 % del país a partir de otra.
// No se suben listas de clientes (hazlo solo cuando tu aviso de privacidad cubra ese uso).
// Edita C: una entrada por marca. paginas_clave: rutas del sitio que valen una audiencia propia (30 días).
const b = (($json.body || $json) || {});
const accion = String(b.accion || 'listar').trim();
const PAIS = 'MX';
const C = {
  'marca-a': { act: '__META_AD_ACCOUNT_A__', page: '__META_PAGE_ID_A__', ig: '__META_IG_ID_A__', pixel: '__META_PIXEL_ID_A__', paginas_clave: ['contacto'] },
  'marca-b': { act: '__META_AD_ACCOUNT_B__', page: '__META_PAGE_ID_B__', ig: '__META_IG_ID_B__', pixel: '__META_PIXEL_ID_B__', paginas_clave: ['contacto'] },
};
const DIA = 86400;
const regla = (tipo, id, dias, campo, op, valor) => ({ inclusions: { operator: 'or', rules: [{ event_sources: [{ type: tipo, id }], retention_seconds: dias * DIA, filter: { operator: 'and', filters: [{ field: campo, operator: op, value: valor }] } }] } });
const BASE = m => {
  const c = C[m];
  const L = [
    { clave: 'sitio_30', nombre: 'Visitantes del sitio · 30 días', rule: regla('pixel', c.pixel, 30, 'url', 'i_contains', ''), prefill: true },
    { clave: 'sitio_180', nombre: 'Visitantes del sitio · 180 días', rule: regla('pixel', c.pixel, 180, 'url', 'i_contains', ''), prefill: true },
    { clave: 'lead_180', nombre: 'Dejaron sus datos en el sitio · 180 días', rule: regla('pixel', c.pixel, 180, 'event', 'eq', 'Lead'), prefill: true },
    ...c.paginas_clave.map(p => ({ clave: 'pagina_' + p.replace(/[^a-z0-9]/gi, '_').toLowerCase() + '_30', nombre: 'Visitaron /' + p + ' · 30 días', rule: regla('pixel', c.pixel, 30, 'url', 'i_contains', p), prefill: true })),
    { clave: 'fb_365', nombre: 'Interactuaron con la página de Facebook · 365 días', rule: regla('page', c.page, 365, 'event', 'eq', 'page_engaged') },
    { clave: 'ig_365', nombre: 'Interactuaron con Instagram · 365 días', rule: regla('ig_business', c.ig, 365, 'event', 'eq', 'ig_business_profile_all') },
    { clave: 'form_90', nombre: 'Abrieron un formulario de Meta · 90 días', rule: regla('lead', c.page, 90, 'event', 'eq', 'opened_form') },
  ];
  return L.map(a => Object.assign(a, { nombre: '[Agente] ' + a.nombre }));
};
const enc = o => Object.entries(o).map(([k, v]) => k + '=' + encodeURIComponent(typeof v === 'string' ? v : JSON.stringify(v))).join('&');
const CAMPOS = 'id,name,subtype,approximate_count_lower_bound,approximate_count_upper_bound,delivery_status,operation_status,time_created,retention_days,description';
let marca = '', crear = [];
if (accion === 'crear' || accion === 'similar') {
  marca = String(b.marca || '');
  if (!C[marca]) throw new Error('Marca inválida: usa ' + Object.keys(C).join(' o ') + '.');
}
if (accion === 'crear') {
  const pedidas = Array.isArray(b.claves) && b.claves.length ? b.claves.map(String) : null;
  crear = BASE(marca).filter(a => !pedidas || pedidas.includes(a.clave)).map(a => ({ que: a.nombre, relative_url: C[marca].act + '/customaudiences', body: enc(Object.assign({ name: a.nombre, description: 'Creada por el agente de Paid (' + a.clave + ')', rule: a.rule }, a.prefill ? { prefill: 'true' } : {})) }));
  if (!crear.length) throw new Error('No hay audiencias base con esas claves.');
} else if (accion === 'similar') {
  const origen = String(b.origen || '');
  if (!/^\d+$/.test(origen)) throw new Error('Falta la audiencia de origen.');
  const nombre = String(b.nombre_origen || origen).replace(/^\[Agente\]\s*/, '').slice(0, 60);
  crear = [{ que: 'Similar 1 % ' + PAIS, relative_url: C[marca].act + '/customaudiences', body: enc({ name: '[Agente] Similar 1 % ' + PAIS + ' · ' + nombre, subtype: 'LOOKALIKE', origin_audience_id: origen, lookalike_spec: { type: 'similarity', ratio: 0.01, country: PAIS } }) }];
} else if (accion !== 'listar') throw new Error('Acción no válida: listar, crear o similar.');
const lote = m => JSON.stringify([
  ...(m === marca ? crear.map((x, i) => ({ method: 'POST', name: 'c' + i, relative_url: x.relative_url, body: x.body })) : []),
  { method: 'GET', name: 'audiencias', relative_url: C[m].act + '/customaudiences?fields=' + CAMPOS + '&limit=200' },
  { method: 'GET', name: 'ig', relative_url: C[m].ig + '/media?fields=id,shortcode,caption,permalink,timestamp,media_type,thumbnail_url,media_url&limit=15' },
]);
const pagina = m => JSON.stringify([
  { method: 'GET', name: 'formularios', relative_url: C[m].page + '/leadgen_forms?fields=id,name,status,leads_count,created_time,locale&limit=50' },
  { method: 'GET', name: 'posts', relative_url: C[m].page + '/published_posts?fields=id,message,created_time,permalink_url,full_picture&limit=15' },
]);
const base = Object.fromEntries(Object.keys(C).map(m => [m, BASE(m).map(a => ({ clave: a.clave, nombre: a.nombre }))]));
return [{ json: { accion, marca, crear: crear.map(x => x.que), base, lote_a: lote('marca-a'), lote_b: lote('marca-b'), pagina_a: pagina('marca-a'), pagina_b: pagina('marca-b') } }];

// Audiencias, formularios y posts recientes por marca, más lo que se creó.
const V = $('Validar').first().json;
const lote = n => { try { return $(n).all().map(i => i.json || {}); } catch (e) { return []; } };
const parse = x => { try { return JSON.parse(x.body || '{}'); } catch (e) { return {}; } };
const err = o => { const e = (o && o.error) || {}; return e.error_user_msg || e.error_user_title || e.message || ''; };
const out = { ok: true, mensaje: '', data: {} };
const creadas = [], fallas = [];
for (const [m, nA, nP] of [['marca-a', 'Audiencias A', 'Página A'], ['marca-b', 'Audiencias B', 'Página B']]) {
  const A = lote(nA), P = lote(nP);
  if (A.length === 1 && A[0].error) { out.data[m] = { error: err(A[0]) || 'Meta no contestó' }; continue; }
  const nCrear = m === V.marca ? V.crear.length : 0;
  A.slice(0, nCrear).forEach((x, i) => { const r = parse(x); if (r.id) creadas.push(V.crear[i]); else fallas.push(V.crear[i] + ': ' + (err(r) || 'código ' + x.code)); });
  const aud = parse(A[nCrear] || {}), ig = parse(A[nCrear + 1] || {});
  const forms = parse(P[0] || {}), posts = parse(P[1] || {});
  const lista = (aud.data || []).map(a => {
    const lo = Number(a.approximate_count_lower_bound), hi = Number(a.approximate_count_upper_bound);
    const clave = ((/\(([a-z_0-9]+)\)$/.exec(a.description || '') || [])[1]) || '';
    return { id: a.id, nombre: a.name, tipo: a.subtype, min: lo > 0 ? lo : null, max: hi > 0 ? hi : null, entrega: (a.delivery_status || {}).description || '',
      estado: (a.operation_status || {}).description || '', creada: a.time_created ? new Date(a.time_created * 1000).toISOString().slice(0, 10) : '', dias: a.retention_days || null, agente: /^\[Agente\]/.test(a.name || ''), clave };
  });
  const tiene = new Set(lista.map(a => a.clave).filter(Boolean));
  out.data[m] = {
    audiencias: lista,
    faltan: (V.base[m] || []).filter(a => !tiene.has(a.clave)),
    formularios: (forms.data || []).map(f => ({ id: f.id, nombre: f.name, estado: f.status, leads: f.leads_count || 0, creado: String(f.created_time || '').slice(0, 10) })),
    posts_fb: (posts.data || []).map(p => ({ id: p.id, texto: String(p.message || '').slice(0, 160), fecha: String(p.created_time || '').slice(0, 10), liga: p.permalink_url, img: p.full_picture || '' })),
    posts_ig: (ig.data || []).map(p => ({ id: p.id, codigo: p.shortcode, texto: String(p.caption || '').slice(0, 160), fecha: String(p.timestamp || '').slice(0, 10), liga: p.permalink, img: p.thumbnail_url || p.media_url || '', tipo: p.media_type })),
    errores: [err(aud), err(ig), err(forms), err(posts)].filter(Boolean),
  };
}
if (V.accion !== 'listar') {
  out.ok = !fallas.length;
  out.mensaje = (creadas.length ? 'Creadas en Meta: ' + creadas.join(', ') + '.' : '') + (fallas.length ? (creadas.length ? ' ' : '') + 'No se pudieron crear: ' + fallas.join('; ') : '');
} else out.mensaje = 'Audiencias al día.';
return [{ json: out }];
